// HLSL port of the GLSL body below. NOT VERIFIED: no DirectX 11 machine was available.
mayaSurfaceShaderOutput GaussianSplatPixel(float4 colorFromGS, float3 uvFromGS)
{
    float distance2 = dot(uvFromGS.xy, uvFromGS.xy);
    if (distance2 > uvFromGS.z * uvFromGS.z)
        discard;
    float falloff = exp(-0.5 * distance2);
    float alpha = colorFromGS.a * falloff;

    mayaSurfaceShaderOutput result;
    result.outColor = colorFromGS.rgb * alpha;
    result.outTransparency = float3(1.0 - alpha, 1.0 - alpha, 1.0 - alpha);
    result.outGlowColor = float3(0.0, 0.0, 0.0);
    result.outMatteOpacity = float3(-1.0e+06, -1.0e+06, -1.0e+06);
    return result;
}


mayaSurfaceShaderOutput GaussianSplatPixel(vec4 colorFromGS, vec3 uvFromGS)
{
    float distance2 = dot(uvFromGS.xy, uvFromGS.xy);
    if (distance2 > uvFromGS.z * uvFromGS.z)
        discard;
    float falloff = exp(-0.5 * distance2);
    float alpha = colorFromGS.a * falloff;

    mayaSurfaceShaderOutput result;
    result.outColor = colorFromGS.rgb * alpha;
    result.outTransparency = vec3(1.0 - alpha);
    result.outGlowColor = vec3(0.0, 0.0, 0.0);
    result.outMatteOpacity = vec3(-1.0e+06, -1.0e+06, -1.0e+06);
    return result;
}
